//! Deterministic synthetic MOC3 fixture generator (master spec section 20).
//!
//! This module produces *test fixtures only*: it never touches `.cmo3` and is
//! not part of the recovery pipeline. It writes minimal, well-formed MOC3
//! files following the documented layout so the inspector can be exercised
//! without using any third-party model data.
//!
//! Every generated byte stream is a pure function of the fixture definition
//! and the chosen format version. Identifiers use a `Synthetic` prefix so the
//! data can never be confused with a real model.

#![forbid(unsafe_code)]
#![deny(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use moc3_ingest::counts::CountInfo;
use moc3_ingest::table::{self, Elem};
use moc3_ingest::MocVersion;

/// A generated fixture: name and bytes.
#[derive(Debug, Clone)]
pub struct Fixture {
    /// File name, e.g. `fixture-001-single-artmesh.moc3`.
    pub name: &'static str,
    /// Complete file bytes.
    pub bytes: Vec<u8>,
}

/// Canvas properties of a synthetic model.
#[derive(Debug, Clone)]
pub struct CanvasSpec {
    /// Pixels per unit.
    pub pixels_per_unit: f32,
    /// Canvas X origin.
    pub origin_x: f32,
    /// Canvas Y origin.
    pub origin_y: f32,
    /// Canvas width.
    pub width: f32,
    /// Canvas height.
    pub height: f32,
    /// Y axis reversed flag.
    pub y_reversed: bool,
}

impl Default for CanvasSpec {
    fn default() -> Self {
        Self {
            pixels_per_unit: 1000.0,
            origin_x: 400.0,
            origin_y: 300.0,
            width: 800.0,
            height: 600.0,
            y_reversed: false,
        }
    }
}

/// Parameter definition (one key table per parameter).
#[derive(Debug, Clone)]
pub struct ParamSpec {
    /// Identifier.
    pub name: String,
    /// Minimum value.
    pub min: f32,
    /// Maximum value.
    pub max: f32,
    /// Default value.
    pub default: f32,
    /// Repeat flag.
    pub repeat: bool,
    /// Decimal places.
    pub decimals: i32,
    /// Key values.
    pub keys: Vec<f32>,
}

impl ParamSpec {
    /// Two-key angle style parameter.
    pub fn two_key(name: &str) -> Self {
        Self {
            name: name.to_string(),
            min: -30.0,
            max: 30.0,
            default: 0.0,
            repeat: false,
            decimals: 2,
            keys: vec![-30.0, 30.0],
        }
    }
}

/// Keyform binding: a set of key table indices.
#[derive(Debug, Clone)]
pub struct BindingSpec {
    /// Key table indices.
    pub tables: Vec<usize>,
}

/// Part definition.
#[derive(Debug, Clone)]
pub struct PartSpec {
    /// Identifier.
    pub name: String,
    /// Parent part.
    pub parent: Option<usize>,
    /// Binding index.
    pub binding: usize,
    /// Visible flag.
    pub visible: bool,
    /// Enabled flag.
    pub enabled: bool,
}

/// Deformer kind.
#[derive(Debug, Clone)]
pub enum DeformerKind {
    /// Warp deformer with a `(rows + 1) x (cols + 1)` grid.
    Warp {
        /// Grid rows.
        rows: u32,
        /// Grid columns.
        cols: u32,
        /// Quad transform flag.
        quad: bool,
    },
    /// Rotation deformer.
    Rotation {
        /// Base angle.
        base_angle: f32,
    },
}

/// Deformer definition.
#[derive(Debug, Clone)]
pub struct DeformerSpec {
    /// Identifier.
    pub name: String,
    /// Kind and kind-specific data.
    pub kind: DeformerKind,
    /// Parent part.
    pub parent_part: Option<usize>,
    /// Parent deformer.
    pub parent_deformer: Option<usize>,
    /// Binding index.
    pub binding: usize,
}

/// Art mesh definition (a quad by default).
#[derive(Debug, Clone)]
pub struct ArtMeshSpec {
    /// Identifier.
    pub name: String,
    /// Parent part.
    pub parent_part: Option<usize>,
    /// Parent deformer.
    pub parent_deformer: Option<usize>,
    /// Texture page number.
    pub texture: u32,
    /// Binding index.
    pub binding: usize,
    /// Masking art mesh indices.
    pub masks: Vec<i32>,
    /// Raw drawable flag byte.
    pub flags: u8,
    /// Quad corner positions (CCW).
    pub quad: [(f32, f32); 4],
    /// Quad UVs.
    pub uv: [(f32, f32); 4],
}

impl ArtMeshSpec {
    /// Quad mesh with the given identifier.
    pub fn quad(name: &str, binding: usize) -> Self {
        Self {
            name: name.to_string(),
            parent_part: None,
            parent_deformer: None,
            texture: 0,
            binding,
            masks: Vec::new(),
            flags: 0,
            quad: [(0.0, 0.0), (100.0, 0.0), (100.0, 100.0), (0.0, 100.0)],
            uv: [(0.1, 0.1), (0.9, 0.1), (0.9, 0.9), (0.1, 0.9)],
        }
    }
}

/// Glue definition connecting two art meshes.
#[derive(Debug, Clone)]
pub struct GlueSpec {
    /// Identifier.
    pub name: String,
    /// First glued art mesh index.
    pub art_mesh_a: usize,
    /// Second glued art mesh index.
    pub art_mesh_b: usize,
    /// Binding index.
    pub binding: usize,
    /// Flat `(weight, position_index)` entries in source order.
    pub info: Vec<(f32, u16)>,
}

/// Draw order group definition.
#[derive(Debug, Clone)]
pub struct DrawGroupSpec {
    /// Items as `(type, index, self_group)` where type 0 = art mesh, 1 = part.
    pub items: Vec<(i64, i64, i64)>,
    /// Maximum draw order.
    pub max_order: i32,
    /// Minimum draw order.
    pub min_order: i32,
}

/// A complete synthetic model description.
#[derive(Debug, Clone, Default)]
pub struct SyntheticModel {
    /// MOC3 version byte.
    pub version: u8,
    /// Canvas info.
    pub canvas: CanvasSpec,
    /// Parameters.
    pub parameters: Vec<ParamSpec>,
    /// Bindings.
    pub bindings: Vec<BindingSpec>,
    /// Parts.
    pub parts: Vec<PartSpec>,
    /// Deformers.
    pub deformers: Vec<DeformerSpec>,
    /// Art meshes.
    pub art_meshes: Vec<ArtMeshSpec>,
    /// Glue entries.
    pub glues: Vec<GlueSpec>,
    /// Draw order groups.
    pub draw_groups: Vec<DrawGroupSpec>,
}

fn align8(value: usize) -> usize {
    (value + 7) & !7usize
}

fn id_bytes(name: &str) -> Vec<u8> {
    let raw = name.as_bytes();
    assert!(raw.len() < 64, "fixture identifier too long: {name}");
    let mut out = vec![0u8; 64];
    out[..raw.len()].copy_from_slice(raw);
    out
}

fn f32_bytes(values: &[f32]) -> Vec<u8> {
    let mut out = Vec::with_capacity(values.len() * 4);
    for value in values {
        out.extend_from_slice(&value.to_le_bytes());
    }
    out
}

fn i32_bytes(values: &[i32]) -> Vec<u8> {
    let mut out = Vec::with_capacity(values.len() * 4);
    for value in values {
        out.extend_from_slice(&value.to_le_bytes());
    }
    out
}

fn u16_bytes(values: &[u16]) -> Vec<u8> {
    let mut out = Vec::with_capacity(values.len() * 2);
    for value in values {
        out.extend_from_slice(&value.to_le_bytes());
    }
    out
}

fn u8_bytes(values: &[u8]) -> Vec<u8> {
    values.to_vec()
}

