/// Build all fixtures deterministically.
pub fn all_fixtures() -> Vec<Fixture> {
    builders()
        .into_iter()
        .map(|(name, builder)| {
            let model = builder();
            Fixture {
                name,
                bytes: build(&model),
            }
        })
        .collect()
}

/// Build one fixture by file name (for tests).
pub fn build_named(name: &str) -> Option<Vec<u8>> {
    builders()
        .into_iter()
        .find(|(fixture_name, _)| *fixture_name == name)
        .map(|(_, builder)| build(&builder()))
}

